            "required": [
                "adapters",
                "image"
            ],
            "title": "Docker specific options",
            "type": "object"
        },
        "documentation_url": {
            "_format": "uri",
            "title": "An optional documentation for using the appliance on vendor website",
            "type": "string"
        },
        "dynamips": {
            "properties": {
                "chassis": {
                    "enum": [
                        "1720",
                        "1721",
                        "1750",
                        "1751",
                        "1760",
