                                    "i82550",
                                    "i82551",
                                    "i82557a",
                                    "i82557b",
                                    "i82557c",
                                    "i82558a",
                                    "i82558b",
                                    "i82559a",
                                    "i82559b",
                                    "i82559c",
                                    "i82559er",
                                    "i82562",
                                    "i82801",
                                    "ne2k_pci",
                                    "pcnet",
                                    "rtl8139",
                                    "virtio",
                                    "virtio-net-pci",
                                    "vmxnet3"
                                ],
                                "title": "Custom adapter type",
                                "type": "string"
                            },
                            "mac_address": {
                                "minimum": 1,
                                "pattern": "^([0-9a-fA-F]{2}[:]){5}([0-9a-fA-F]{2})$",
