                },
                "kvm": {
                    "enum": [
                        "require",
                        "allow",
                        "disable"
                    ],
                    "title": "KVM requirements"
                },
                "options": {
                    "title": "Optional additional qemu command line options",
                    "type": "string"
                },
                "process_priority": {
                    "enum": [
                        "realtime",
                        "very high",
                        "high",
                        "normal",
                        "low",
                        "very low",
                        "null"
                    ],
                    "title": "Process priority for QEMU"
                },
                "ram": {
                    "title": "Ram allocated to the appliance (MB)",
                    "type": "integer"
                }
            },
            "required": [
                "adapter_type",
                "adapters",
                "ram",
                "arch",
                "console_type",
                "kvm"
            ],
            "title": "Qemu specific options",
            "type": "object"
        },
