            "enum": [
                1,
                2,
                3,
                4,
                5,
                6
            ],
            "title": "Version of the registry compatible with this appliance"
        },
        "status": {
            "enum": [
                "stable",
                "experimental",
                "broken"
            ],
            "title": "Document if the appliance is working or not"
        },
        "symbol": {
            "title": "An optional symbol for the appliance",
            "type": "string"
        },
        "usage": {
            "title": "How to use the appliance",
            "type": "string"
        },
        "vendor_name": {
            "title": "Name of the vendor",
            "type": "string"
        },
        "vendor_url": {
            "_format": "uri",
            "title": "Website of the vendor",
            "type": "string"
        },
        "versions": {
            "items": {
                "properties": {
                    "idlepc": {
                        "pattern": "^0x[0-9a-f]{8}",
                        "type": "string"
                    },
                    "images": {
                        "properties": {
                            "bios_image": {
                                "title": "Bios image",
                                "type": "string"
                            },
                            "cdrom_image": {
                                "title": "cdrom image",
                                "type": "string"
                            },
                            "hda_disk_image": {
                                "title": "Hda disk image",
                                "type": "string"
                            },
                            "hdb_disk_image": {
                                "title": "Hdc disk image",
                                "type": "string"
                            },
                            "hdc_disk_image": {
                                "title": "Hdd disk image",
                                "type": "string"
                            },
                            "hdd_disk_image": {
                                "title": "Hdd diskimage",
                                "type": "string"
                            },
                            "image": {
                                "title": "OS image",
                                "type": "string"
                            },
                            "initrd": {
                                "title": "Initrd disk image",
                                "type": "string"
                            },
                            "kernel_image": {
                                "title": "Kernel image",
                                "type": "string"
                            }
                        },
                        "title": "Images used for this version",
                        "type": "object"
                    },
                    "name": {
                        "title": "Name of the version",
                        "type": "string"
                    }
                },
                "required": [
                    "name"
                ],
                "title": "A version of the appliance",
                "type": "object"
            },
            "title": "Versions of the appliance",
            "type": "array"
        }
    },
    "required": [
        "name",
        "category",
        "description",
        "vendor_name",
        "vendor_url",
        "product_name",
        "registry_version",
        "status",
        "maintainer",
        "maintainer_email"
    ],
    "title": "JSON schema validating a GNS3 appliance",
    "type": "object"
}

